CREATE FUNCTION calculate_rcp(vehicle_reg VARCHAR)
RETURNS VARCHAR AS $ $
DECLARE 
    distance_done NUMERIC;
    distance_left NUMERIC;
    completion_status VARCHAR;
BEGIN
    -- Fetch the distance information for the vehicle
    SELECT 
        distdonekm, 
        distleftkm
    INTO 
        distance_done, 
        distance_left
    FROM 
        transportinfo
    WHERE 
        vehiclereg = vehicle_reg;

    -- Determine the completion status based on the distance information
    IF distance_done IS NULL AND distance_left IS NULL THEN
        completion_status := 'No distance information available';
    ELSIF distance_left <= 0 THEN
        completion_status := 'Completed';
    ELSE
        completion_status := 'In Progress';
    END IF;

    RETURN completion_status;
END
$ $ LANGUAGE plpgsql;

